/* selectUserAuth - Lee JiSeob */
SELECT
C.INQ_BUTTON_USE_YN, C.DTL_INQ_BUTTON_USE_YN, C.INITL_BUTTON_USE_YN, C.REG_BUTTON_USE_YN, C.MDFCN_BUTTON_USE_YN, C.DEL_BUTTON_USE_YN, C.MNG_BUTTON_USE_YN
FROM SAB250 C /* 사용자별 메뉴 권한 */
WHERE C.MENU_NO = #{AUTH_MENU_NO} AND C.USER_ID = #{USER_ID}
